mapper.update:
UPDATE `reservation`
SET `status`    = 2,
    `version`   = `version` + 1,
    `update_at` = #{now}
WHERE `user_id`        = #{userId}
  AND `reservation_no` = #{reservationNo}
  AND `status`         = 0
  AND `version`        = #{version}
  AND `valid_until`   >= #{now}

UPDATE `reservation`
SET `status`      = 1,
    `verified_at` = #{verifiedAt},
    `version`     = `version` + 1,
    `update_at`   = #{verifiedAt}
WHERE `user_id`        = #{userId}
  AND `reservation_no` = #{reservationNo}
  AND `status`         = 0
  AND `version`        = #{version}
  AND `valid_until`   >= #{verifiedAt}

UPDATE `reservation`
SET `status`    = 3,
    `version`   = `version` + 1,
    `update_at` = #{now}
WHERE `user_id`     = #{userId}
  AND `reservation_no` = #{reservationNo}
  AND `status`      = 0
  AND `valid_until` < #{now}
